H.background();
const a = (Math.abs(P.a) < 1e-9) ? 1 : P.a, b = P.b, c = P.c;
const step = Math.max(0, Math.min(2, Math.round(P.step)));
const x = (c - b) / a;
const w = H.W, h = H.H;
// three equation lines, revealed by step, with a sweeping highlight
const lines = [
  { lhs: "a·x + b = c", sub: "start:  " + a.toFixed(1) + "·x + " + b.toFixed(1) + " = " + c.toFixed(1) },
  { lhs: "a·x = c − b", sub: "subtract " + b.toFixed(1) + " from both sides  →  " + a.toFixed(1) + "·x = " + (c - b).toFixed(2) },
  { lhs: "x = (c − b) / a", sub: "divide both sides by " + a.toFixed(1) + "  →  x = " + x.toFixed(2) }
];
const y0 = 120, dy = 110;
for (let i = 0; i <= step; i++) {
  const yy = y0 + i * dy;
  const active = (i === step);
  const glow = active ? (4 + 3 * Math.sin(t * 3)) : 0;
  H.rect(60, yy - 34, w - 120, 64, { fill: active ? H.colors.panel : "#11192e", stroke: active ? H.colors.accent : H.colors.grid, width: 1.5 + glow * 0.2, radius: 10 });
  H.text(lines[i].lhs, 84, yy - 2, { color: H.colors.ink, size: 22, weight: 700 });
  H.text(lines[i].sub, 84, yy + 22, { color: active ? H.colors.good : H.colors.sub, size: 13 });
  if (i > 0) {
    const ax = w * 0.5;
    H.arrow(ax, yy - dy + 30, ax, yy - 34, { color: H.colors.accent2, width: 2, head: 8 });
  }
}
// animated check: plug x back in, dot slides to balance
const px = 60 + (w - 120) * (0.5 + 0.45 * Math.sin(t * 1.2));
H.circle(px, h - 36, 6, { fill: H.colors.warn });
H.text("Solve a multi-step equation by UNDOING operations", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a=" + a.toFixed(1) + "  b=" + b.toFixed(1) + "  c=" + c.toFixed(1) + "   step " + step + "/2    solution x = " + x.toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
H.text("check: a·x + b = " + (a * x + b).toFixed(2) + " = c ✓", 60, h - 30, { color: H.colors.good, size: 13 });
